import {gapSummary,outcomeScenario,regionalSummary,regionalSignals,TRACK_LABELS,SIGNAL_LABELS,provisionalTracks} from './evidence.js?v=1.2.1';

export function uncertaintyPanel(rs,basis,assumption,ui){
  const {panel,percent}=ui,s=outcomeScenario(rs,basis,assumption),g=gapSummary(rs);
  return panel('Missing data and assumptions','MISSING DATA & SCENARIOS',`<div class="evidence-content"><div class="gap-grid">${[['research_missing','Research area unclassified'],['outcome_missing','First job / career path unverified'],['year_missing','First job recorded · year unverified'],['role_missing','Employer recorded · job type unverified']].map(([k,t])=>`<button class="gap-card" data-quality="${k}"><strong>${g[k]}</strong><span>${t}</span></button>`).join('')}</div><p class="chart-note">Select a count to see the records. Provisional research labels are available for ${g.provisional} records. The first-job and missing-year groups are disjoint; other gaps may overlap. Unverified fields remain unknown.</p><details class="scenario-details"><summary>Explore how unknown outcomes affect the academic faculty share</summary><p>Among known outcome categories: ${s.faculty} / ${s.known} = <strong>${percent(s.facultyShare)}</strong> in the academic faculty category, which includes title-based inference. Another ${s.unknown} records have unknown categories. This scenario assumes those records eventually fall into the four observed outcome categories.</p><label for="scenario-share">Assumed academic faculty share among unknown outcomes: <output id="scenario-assumption">${Math.round(assumption*100)}%</output></label><input id="scenario-share" type="range" min="0" max="100" step="5" value="${Math.round(assumption*100)}"><p class="scenario-result">Scenario academic faculty share: <strong id="scenario-result">${percent(s.scenario)}</strong></p><p>Calculation: (${s.faculty} + ${s.unknown} × assumed share) ÷ ${s.denominator}. Extreme-assumption range: ${percent(s.lower)}–${percent(s.upper)}.</p><p class="chart-note">The 50% starting point is an assumption, not a forecast; the range is not a confidence interval. Only collected records enter the calculation. Deferred and current-market candidates are excluded, and missing years are not imputed into annual charts.</p></details></div>`);
}
export function regionalDetail(r,ui){
  const {esc,external,region}=ui;
  const signals=[...regionalSignals(r,'CN'),...regionalSignals(r,'HK')];
  if(!signals.length)return '<p class="chart-note">No explicit job-search interest or recruiting event for Mainland China or Hong Kong is recorded here. This does not establish the person’s preferences.</p>';
  return '<ul class="event-list">'+signals.map(s=>`<li><strong>${esc(SIGNAL_LABELS[s.kind])} · ${region(s.region)}</strong><span>${esc(s.observed_date)} · ${esc(s.institution||'Personal statement')} · ${esc(s.event_status==='announced'?'Announced · attendance not independently confirmed':'Reported in source')}</span><p><span class="muted">Original source notes:</span> ${esc(s.evidence)}</p>${external(s.source_url,'View original evidence')}</li>`).join('')+'</ul><p class="chart-note">Historical events describe evidence available at the time. Recruiting activity does not confirm a hire or current interest; ordinary seminars are tracked separately.</p>';
}
export function inferenceDetail(r,ui){
  const {esc,external}=ui;
  if(!provisionalTracks(r).length)return '';
  const x=r.research_inference;
  return `<div class="inference-note"><strong>Provisional research classification: ${x.tracks.map(t=>TRACK_LABELS[t]).join(' · ')}</strong><p><span class="muted">Original source notes:</span> ${esc(x.reason)}</p><p>Evidence: ${x.source_urls.map(u=>external(u,'Original research source')).join(' · ')} · Checked ${esc(x.checked_at)}</p><p>Based on research content; an explicit classification has not been verified. Enable provisional classifications in the research filters to include these labels.</p></div>`;
}
export function chinaPanel(base,rs,filters,ui){
  const {panel,table,option,region}=ui;
  const s=regionalSummary(base,filters.china_region,filters.basis),regionalLabel=({CN:'Mainland China',HK:'Hong Kong',CN_HK:'Mainland China + Hong Kong'})[filters.china_region]||region(filters.china_region);
  return panel('Mainland China and Hong Kong','REGIONAL MARKET EVIDENCE',`<div class="evidence-content"><p>Explore published placements, explicit job-search interest and recruiting events. All filters above apply; Mainland China and Hong Kong can be viewed separately.</p><div class="regional-controls"><label>Region<select id="china-region">${[['CN','Mainland China'],['HK','Hong Kong'],['CN_HK','Mainland China + Hong Kong']].map(([v,t])=>option(v,t,filters.china_region)).join('')}</select></label><label>Evidence type<select id="china-kind">${[['placement','Published placement · job type may be unverified'],['faculty','Academic faculty · title-based category'],['interest','Self-reported interest in this regional job market'],['recruiting','Recruiting event · does not confirm a hire'],['any','Placement, explicit interest or recruiting event'],['exchange','Academic exchange · separate view']].map(([v,t])=>option(v,t,filters.china_kind)).join('')}</select></label></div><div class="gap-grid">${[['placement','Regional placement records'],['faculty','Academic faculty · title-based category'],['interest','Recorded explicit interest'],['recruiting','Recorded recruiting events']].map(([k,t])=>`<button class="gap-card" data-china-kind="${k}"><strong>${s[k]}</strong><span>${t}</span></button>`).join('')}</div><p class="chart-note">Groups may overlap. Zero means no corresponding evidence has been collected. Another ${s.exchange} people have academic-exchange records, which are excluded from job-search evidence. Historical placements do not establish current availability.</p><details><summary>Background filters and coverage limits</summary><p>Undergraduate-region filters support comparisons; education, names and ancestry do not establish job-search preferences or citizenship. These evidence records are not a complete survey of regional applicants.</p></details></div>`)+panel(`Matching researchers · ${rs.length}`,`${regionalLabel||'Mainland China + Hong Kong'} · PUBLIC RECORDS`,table(rs)+`<div class="panel-footer"><button class="button secondary" id="export-csv">Export filtered researchers as CSV</button></div>`)+panel('How regional evidence is collected','SOURCE CHECKLIST',`<div class="prose"><p>Records require a dated personal statement about the regional job market or an organizer’s explicitly identified Job Talk / Recruitment Seminar announcement. Each keeps the person, institution, date, source and original evidence.</p><p>The APMA ${ui.external('https://ma.szu.edu.cn/info/1048/8636.htm','Marketing Academic Job Market Forum')} is a research lead. A specific person and session must be verified before inclusion; a JMP title or ordinary seminar alone is insufficient.</p></div>`);
}
